// Parses simple comma-separated lists and key=value pairs.

export function parseList(text) {
  // TODO: handle quoted items that contain commas
  if (text === '') return [];
  return text.split(',').map((item) => item);
}

export function parsePairs(text) {
  const pairs = parseList(text).map((pair) => pair.split('='));
  return Object.fromEntries(pairs);
}

export function countItems(text) {
  return parseList(text).length;
}

// Small array helpers.

export function unique(items) {
  return [...new Set(items)];
}

// TODO: support a custom size per chunk
export function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// Tiny test runner. Each check prints as it runs, with a short pause between them.
import { parseList, parsePairs, countItems } from './src/parser.js';
import { unique, chunk } from './src/util.js';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
let failed = 0;

async function check(name, actual, expected) {
  await sleep(350);
  if (same(actual, expected)) console.log(`PASS  ${name}`);
  else {
    failed++;
    console.log(`FAIL  ${name}\n      expected ${JSON.stringify(expected)}\n      got      ${JSON.stringify(actual)}`);
  }
}

await check('parseList splits on commas', parseList('a,b,c'), ['a', 'b', 'c']);
await check('parseList trims whitespace', parseList('a, b ,c'), ['a', 'b', 'c']);
await check('parseList of empty string', parseList(''), []);
await check('parsePairs builds an object', parsePairs('x=1, y=2'), { x: '1', y: '2' });
await check('countItems counts', countItems('a,b'), 2);
await check('unique removes repeats', unique([1, 1, 2]), [1, 2]);
await check('chunk groups items', chunk([1, 2, 3], 2), [[1, 2], [3]]);

console.log(failed ? `\n${failed} failed` : '\nall passed');
process.exit(failed ? 1 : 0);

